SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_mental_f20_w(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
  hosp_area varchar(14) NOT NULL,
	result1 int(10) DEFAULT 0,
	result2 int(10) DEFAULT 0,
	result3 int(10) DEFAULT 0,
	result4 int(10) DEFAULT 0,
	PRIMARY KEY (id,b_year,hosp_area),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year),
	KEY (hosp_area)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_mental_f20_w WHERE id=@id AND b_year=(@b_year+543);
CALL AddCol('hdc','s_mental_f20_w','result3','int(10) DEFAULT 0 ');
CALL AddCol('hdc','s_mental_f20_w','result4','int(10) DEFAULT 0 ');

INSERT IGNORE INTO s_mental_f20_w (
SELECT
@id,h.hoscode,CONCAT(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,CONCAT(h.hoscode,'-',h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2))  hosp_area
,COUNT(DISTINCT CONCAT(f.diag_hospcode,'-',f.cid)) result1
,0 as  result2
,COUNT(DISTINCT CONCAT(d.hospcode,'-',d.cid)) result3
,COUNT(DISTINCT CONCAT(d.hospcode,'-',d.cid,'-',d.seq,'-',d.date_serv)) result4
FROM tmp_f20 f INNER JOIN chospital h ON f.diag_hospcode=h.hoscode
LEFT JOIN tmp_diag_opd  d ON f.diag_hospcode=d.hospcode AND f.cid=d.cid
			AND SUBSTR(d.DIAGCODE,1,3) IN ('F20') AND d.date_serv BETWEEN @start_d AND @end_d
	WHERE  h.provcode IN(@prov_c)
 AND TIMESTAMPDIFF(year,f.birth,f.diag_date_serv) >= 15 
 GROUP BY hoscode
);
UPDATE  s_mental_f20_w  s INNER JOIN
(
SELECT c.hospcode,CONCAT(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) as areacode
,(@b_year+543) as b_year
,COUNT(DISTINCT t.cid) result2
FROM tmp_f20 t INNER JOIN cvillage_hosp c ON t.final_addr=c.villcode
INNER JOIN chospital h ON c.hospcode=h.hoscode
WHERE  TIMESTAMPDIFF(year,t.birth,t.diag_date_serv) >= 15 
 GROUP BY c.hospcode
) a ON s.hospcode=a.hospcode AND s.areacode=a.areacode AND s.b_year=a.b_year
SET s.result2=a.result2;

INSERT IGNORE INTO s_mental_f20_w (
SELECT 
@id,h.hoscode,CONCAT(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,CONCAT(h.hoscode,'-',h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2))  hosp_area
,0 as result1,COUNT(DISTINCT t.cid) result2,0 as result3,0 as result4
FROM tmp_f20 t INNER JOIN cvillage_hosp c ON t.final_addr=c.villcode
INNER JOIN chospital h ON c.hospcode=h.hoscode
WHERE  TIMESTAMPDIFF(year,t.birth,t.diag_date_serv) >= 15 
 GROUP BY c.hospcode
);
